export const REPOSITORY: Toolbox = {
  name: 'repository',
  idea: 'the repository watched: every workspace, branch, tag and release here compared with the remote and the archive online, every disagreement a lead',
  tools: [repository],
  examples: [
    { id: 'repository-machine-actions', tool: 'repository', theorem: 'textbook_machine_allow_list', arguments: { machine: { actions: true } }, shows: 'The developer machine managed through the MCP, securely: an allow-list of thirteen local actions — six reads of the tree\'s state (status, log, how far from the remote, tags, diff, the runtime) and seven writes the workflows already name (next, the strict pre-deploy check, stage, commit through the hooks, push through pre-push, a merge of a named branch under the pre-commit rules, the generators in their order) — served by a local server bound to the loopback alone, behind a token, with no shell.', expect: (s) => (s.actions.length === 14 && s.reads === 6 && s.writes === 8 && s.actions.find((a: { id: string }) => a.id === 'dispatch').workflow === 'pre-push' && s.actions.find((a: { id: string }) => a.id === 'dispatch').needs === 'confirm' && s.actions.find((a: { id: string }) => a.id === 'merge').workflow === 'pre-commit' && s.actions.find((a: { id: string }) => a.id === 'push').needs === 'confirm' && s.actions.find((a: { id: string }) => a.id === 'commit').workflow === 'pre-commit' ? null : JSON.stringify(s.actions.map((a: { id: string }) => a.id))) },
    { id: 'repository-machine-refused', tool: 'repository', theorem: 'textbook_machine_allow_list', arguments: { machine: { plan: { action: 'rm -rf /' } } }, shows: 'Anything the allow-list does not name is refused before anything runs, with the case the court computes: no arbitrary command reaches the machine.', expect: (s) => (s.allowed === false && s.court.rule === 'route' && /^[0-9a-f-]{36}$/.test(s.court.case) && !('command' in s) ? null : JSON.stringify(s)) },
    { id: 'repository-machine-push-unconfirmed', tool: 'repository', theorem: 'textbook_machine_allow_list', arguments: { machine: { plan: { action: 'push' } } }, shows: 'A write that leaves the machine waits for the user: a push without the user\'s confirmation is refused with the court\'s case, and with it the pre-push rules decided by theorems still have the last word.', expect: (s) => (s.allowed === false && s.court.rule === 'role' && /confirmation/.test(s.refused) ? null : JSON.stringify(s)) },
    { id: 'repository-machine-record', tool: 'repository', theorem: 'textbook_leaks_redacted', arguments: { machine: { record: { action: 'status', command: { cmd: 'git', args: ['status', '--porcelain=v1', '--branch'] }, status: 0, stdout: '## main...origin/main [ahead 3]\n M /Users/dev/tree/src/a.ts\n?? /Users/dev/notes.txt reached at 10.0.0.7', stderr: '', ms: 12, root: '/Users/dev/tree', home: '/Users/dev' } } }, shows: 'A run judged before anyone sees it: the paths made relative to the tree (the root as ., the home as ~), a leak that remains redacted by its kind, the whole a docket entry at its content address with its SHA-256, the shape the docket and the Payload entries address.', expect: (s) => (s.ok === true && s.entry.kind === 'machine' && s.entry.body.output.includes('./src/a.ts') && s.entry.body.output.includes('~/notes.txt') && !s.entry.body.output.includes('/Users/') && s.entry.body.output.includes('[private-ip]') && s.redacted === 1 && /^[0-9a-f-]{36}$/.test(s.entry.id) && s.entry.sha256.length === 64 ? null : JSON.stringify(s.entry?.body)) },
    { id: 'repository-predeploy', tool: 'repository', theorem: 'textbook_bindings_bound', arguments: { workflow: 'pre-deploy', facts: { receipt: { steps: [{ name: 'typecheck', status: 'green' }] }, openNext: { worker: true, assets: true, builtAt: 2, sourcesAt: 1 }, wrangler: { bindings: ['ASSETS', 'D1', 'R2', 'KV', 'QPU', 'AI'], placeholders: 2, flags: ['nodejs_compat', 'webcrypto_modern_algorithms'], d1: ['qpu-site'], r2: ['qpu-media'], kv: [] }, account: null, observability: { requests: 12000, errors5xx: 3, window: '24h' }, usage: { workersRequestsPerDay: 12000, d1RowsReadPerDay: 40000 } } }, shows: 'The strict pre-check before a deploy of the Payload app over OpenNext on Cloudflare, every rule decided by its theorem over the facts: the flow green, the bundle built after its sources, every binding the adapters need declared and the flags set — but two placeholder ids left — the account not read yet, three server errors in twelve thousand requests within the bound, the usage within the free tiers so the bill is zero and the cheapest licence all margin; a violated or unmeasured rule refuses the deploy and names the case for the court.', expect: (s) => (s.decision.allowed === false && s.decision.violated.includes('bound') && s.decision.unknown.includes('account') && s.decision.rules.find((x: { rule: string }) => x.rule === 'observed').holds === true && s.decision.rules.find((x: { rule: string }) => x.rule === 'billed').holds === true && s.decision.rules.find((x: { rule: string }) => x.rule === 'built').holds === true && s.decision.court.tool === 'legal' ? null : JSON.stringify(s.decision.rules.map((x: { rule: string; holds: boolean | null }) => x.rule + ':' + x.holds))) },
    { id: 'repository-workflow', tool: 'repository', theorem: 'textbook_hook_workflows', arguments: { workflow: 'pre-push' }, shows: 'Pre-commit and pre-push as client MCP workflows: one door answers each git hook (and the CI) as steps — a command of next, the e2e gate, an imprint, the trailers, the unit\'s signature over the hosted door — with its strictness; the hook script (scripts/hook.ts) walks the steps and decides nothing itself: pre-push is the fast offline flow then the e2e gate, strict; pre-commit never blocks; four hooks and the CI are five workflows.', expect: (s) => (s.workflows === 6 && s.workflow.name === 'pre-push' && s.workflow.strict === true && s.workflow.steps.length === 2 && s.workflow.steps[0].args.includes('--strict') && s.workflow.steps[1].id === 'e2e' && s.workflow.steps.every((x: { strict?: boolean }) => x.strict === true) ? null : JSON.stringify(s.workflow)) },
    { id: 'repository-predeploy-docket', tool: 'repository', theorem: 'textbook_bindings_bound', arguments: { workflow: 'pre-deploy', facts: { receipt: { steps: [{ name: 'typecheck', status: 'green' }] }, openNext: { worker: true, assets: true, builtAt: 2, sourcesAt: 1 }, config: '{\n  // the default deploy\n  "assets": { "binding": "ASSETS" }, "compatibility_flags": ["nodejs_compat", "webcrypto_modern_algorithms"], "d1_databases": [{ "binding": "D1", "database_name": "site", "database_id": "<the tenant\'s>" }], "r2_buckets": [{ "binding": "R2", "bucket_name": "media" }], "kv_namespaces": [{ "binding": "KV", "id": "<the tenant\'s>" }], "services": [{ "binding": "QPU", "service": "qpu" }], "ai": { "binding": "AI" } }', docket: [{ createdAt: '2026-01-01T00:00:00Z', body: { kind: 'account', d1: ['site'], r2: [], kv: ['k1'], workers: [] } }, { createdAt: '2026-01-02T00:00:00Z', body: { kind: 'account', d1: ['site'], r2: ['media'], kv: ['k1'], workers: ['qpu'] } }, { createdAt: '2026-01-02T00:00:01Z', body: { kind: 'resource', binding: 'D1', name: 'site', id: 'd1' } }, { createdAt: '2026-01-02T00:00:02Z', body: { kind: 'resource', binding: 'KV', name: 'site', id: 'k1' } }] } }, shows: 'The pre-deploy facts from the RAID, raw: the deploy configuration\'s text and the docket\'s documents as the Payload MCP answered them, folded by the core — the newest account is the account, every resource fills its binding\'s placeholder id — so the client that gathers them names no provider and no resource; built, bound and present in the account hold, observability and usage wait in the docket.', expect: (s) => (s.decision.violated.length === 0 && s.decision.unknown.join() === 'observed,billed' && s.decision.rules.find((x: { rule: string }) => x.rule === 'bound').holds === true && s.decision.rules.find((x: { rule: string }) => x.rule === 'account').holds === true ? null : JSON.stringify(s.decision.rules.map((x: { rule: string; holds: boolean | null; evidence: string }) => x.rule + ':' + x.holds + ':' + x.evidence))) },
    { id: 'repository-decide-push', tool: 'repository', theorem: 'textbook_version_sequential', arguments: { workflow: 'pre-push', facts: { penalties: { open: 0, openKeys: [] }, sole: { branches: ['main'], worktrees: 1 }, published: { head: 'f10a05a9', branch: 'main', build: 'green', publish: 'green' }, receipt: { steps: [{ name: 'typecheck', status: 'green' }, { name: 'e2e', status: 'skipped' }] }, approval: { approved: true, violation: null, agrees: true, represents: '1.4.0+e1.abcd', package: '1.4.0+e1.abcd' }, e2e: { uncorrectable: 0, agree: 229, erased: 13 } } }, shows: 'The strict rules of when to push, decided by theorems over the facts the hook client hands back after its steps: the flow green (no red step), the version sequential and representing the package the configs step approved, the gate decoded with nothing uncorrectable — all three hold here, so the push is allowed; a violated or unmeasured rule refuses it and names the case for the court.', expect: (s) => (s.decision.allowed === true && s.decision.rules.length === 6 && s.decision.rules.every((r: { holds: boolean; theorem: string }) => r.holds === true && r.theorem.startsWith('textbook_')) && s.decision.court === null && s.rules === WORKFLOW_RULES.length ? null : JSON.stringify(s.decision)) },
    { id: 'repository-refuse-commit', tool: 'repository', theorem: 'textbook_commit_green', arguments: { workflow: 'pre-commit', facts: { receipt: { steps: [{ name: 'typecheck', status: 'green' }, { name: 'test', status: 'red' }] } } }, shows: 'A commit refused by the rule: one red step in the receipt violates the green rule, the decision names the step and the case the court computes (git pre-commit, the collision rule), and the hook client stops.', expect: (s) => (s.decision.allowed === false && s.decision.violated[0] === 'green' && /red: test/.test(s.decision.rules[0].evidence) && s.decision.court.tool === 'legal' ? null : JSON.stringify(s.decision)) },
    { id: 'repository-watch', tool: 'repository', arguments: { local: LOCAL, answers: ANSWERS }, shows: 'Fixture facts against fixture answers: two local branches unpushed, one remote branch not here, a local tag not pushed, a remote tag not fetched, a moved tag, a release whose tag is gone, a version with a tag and no release, a Zenodo version without a release, a second workspace, the registry behind the tree, a red workflow at the remote, two workflows only at the remote: fourteen leads.', expect: (s) => (s.phase === 'watch' && s.leads === 14 && s.watch.npm.behind === true && s.watch.runs.red.join() === 'publish' && s.watch.workflows.onlyRemote.join() === 'publish.yml,codeql.yml' && s.watch.tags.mismatch.join() === 'v1.4.0' && s.watch.releases.withoutTag.join() === 'v0.9.0' && s.watch.zenodo.withoutRelease.join() === '1.1.1' ? null : `${s.phase} ${s.leads} leads: ${s.watch?.leads.map((l: { id: string }) => l.id).join(', ')}`) },
  ],
  skill: {
    instructions: 'The client gathers with git: the remote url, HEAD, the branch, package.json\'s version, worktree list, every branch with its upstream and head, every tag with its commit, and the concept DOI from .zenodo.json\'s related identifiers; calls repository for the requests; fetches them (GitHub needs no token for public reads); calls again with the answers; writes repository.json and the page; its leads join the next-leads docket. Offline, the local facts alone are written.',
    directions: ['server only: fixture facts against fixture answers give every kind of lead once', 'client → server: git facts in, GitHub and Zenodo bodies in', 'toolbox → toolbox: requests checked against the contracts discovery found; leads feed readiness'],
    selftest: () => {
      const checks: { id: string; passed: boolean; evidence: string }[] = []
      const check = (id: string, passed: boolean, evidence: string) => checks.push({ id, passed, evidence })
      const reqs = watchRequestsOf(LOCAL, { 'api.github.com': ['/repos/{owner}/{repo}/branches', '/repos/{owner}/{repo}/tags', '/repos/{owner}/{repo}/releases'] })
      check('repository:requests', reqs.length === 7 && reqs.filter((r) => r.contracted === 'yes').length === 3 && reqs.some((r) => r.purpose === 'zenodo') && reqs.some((r) => r.purpose === 'npm') && reqs.some((r) => r.purpose === 'runs') && reqs.some((r) => r.purpose === 'workflows'), `${reqs.length} requests, ${reqs.filter((r) => r.contracted === 'yes').length} inside GitHub's contract`)
      check('repository:no-remote', watchRequestsOf({ ...LOCAL, remote: null, conceptDoi: null, pkg: null }).length === 0 && ownerRepoOf('git@github.com:uuidna/qpu.git')?.repo === 'qpu', 'no remote, no requests; an ssh remote parses')
      const w = watchOf(LOCAL, ANSWERS)
      const ids = w.leads.map((l) => l.id)
      check('repository:leads', ids.includes('branch-only-local-rebuild-phase-1') && ids.includes('branch-only-remote-clean') && ids.includes('tag-only-local-waves-complete') && ids.includes('tag-only-remote-v1-0-1') && ids.includes('tag-moved-v1-4-0') && ids.includes('release-without-tag-v0-9-0') && ids.includes('version-without-release-v1.4.0') && ids.includes('zenodo-without-release-1-1-1') && ids.includes('workspace-qpu-2') && ids.includes('npm-behind-1-0-1') && ids.includes('workflow-red-publish') && ids.includes('workflow-only-remote-publish-yml') && !ids.some((i) => i.startsWith('version-without-tag')), ids.join(', '))
      const offline = watchOf(LOCAL, [])
      check('repository:offline', offline.branches.remote === null && offline.leads.length === 1 && offline.leads[0]!.id === 'workspace-qpu-2' && offline.refusals.length === 0, 'without answers only the local facts speak: the second workspace')
      const refused = watchOf(LOCAL, [{ ...ANSWERS[0]!, status: 403, text: 'rate limited' }])
      check('repository:refusal', refused.refusals.length === 1 && refused.branches.remote === null, 'a refused request is recorded, never read as agreement')
      check('repository:page', watchPageOf(w, '2026-01-01').includes('| tags | 3 | 3 | 1 | waves-complete | v1.0.1 |'), 'the page renders the tags row')
            {
        const viaMcp = watchRequestsOf(LOCAL, {}, 'mcp')
        const stream = (v: unknown) => 'event: message\ndata: ' + JSON.stringify({ jsonrpc: '2.0', id: 1, result: { content: [{ type: 'text', text: JSON.stringify(v) }] } }) + '\n\n'
        const mcpAnswers: Answer[] = [
          { ...viaMcp[0]!, status: 200, text: stream([{ name: 'main', commit: { sha: '1111' } }, { name: 'rebuild/phase-1', commit: { sha: '2222' } }]) } as Answer,
          { ...viaMcp[1]!, status: 200, text: stream([{ name: 'v1.4.0', commit: { sha: '4444' } }]) } as Answer,
          { ...viaMcp[2]!, status: 200, text: stream([{ tag_name: 'v1.4.0', name: 'v1.4.0', draft: false, prerelease: false, published_at: '2026-10-01T00:00:00Z' }]) } as Answer,
        ]
        const wm = watchOf(LOCAL, mcpAnswers)
        check('repository:github-mcp-doors', viaMcp.filter((r) => r.via === 'mcp').length === 3 && viaMcp.every((r) => r.via !== 'mcp' || (r.method === 'POST' && (r.body as { params: { name: string } }).params.name.startsWith('list_'))) && wm.branches.remote === 2 && wm.tags.remote === 1 && wm.releases.count === 1, `three doors (${viaMcp.filter((r) => r.via === 'mcp').map((r) => (r.body as { params: { name: string } }).params.name).join(', ')}), their event-stream answers read into ${wm.branches.remote} branches, ${wm.tags.remote} tags, ${wm.releases.count} release(s)`)
      }
      return { passed: checks.every((c) => c.passed), checks }
    },
  },
}
